  switch (addServerWindow) {
    case "Create Server":
      return <CreateServer />;

    case "Join Server":
      return <JoinServer />;

    case "About Server":
      return <AboutServer />;

    case "Customize Server":
      return <CustomizeServer />;

    default:
      return <CreateServer />;
  }
}

